// muapi Studio "Apps" for the Edit Studio.
//
// Turns src/data/muapiStudioAppsMap.json (generated by scripts/build-muapi-apps-map.mjs) plus our own
// original prompts (src/data/muapiAppPrompts.json, not muapi's text) into tool objects the Edit Studio
// can show next to its built-in tools. Nothing here touches EDIT_TOOLS.
//
// An app that is already in this repo (same endpoint / same job, see `existingIn` in the map) is not
// added again.
import appsMap from '../data/muapiStudioAppsMap.json';
import prompts from '../data/muapiAppPrompts.json';

export const APP_CATEGORY_ORDER = [
  'professional', 'enhance-style', 'face-identity', 'video-editing', 'ads', 'games-characters', 'trending-templates',
];

const V2V_MODELS = new Set(['ai-video-face-swap', 'video-background-remover']);
const THIS_REPO = 'remix-new-editor';

/** True when the same tool already exists in this repo (so we do not add a second copy). */
export function isAlreadyInThisRepo(app) {
  return (app.existingIn || []).some((x) => x.repo === THIS_REPO && x.match !== 'similar');
}

const durationLabel = (v) => `${v}s`;
const SELECT_LABELS = { duration: durationLabel };

function mediaSource(input, isPrimary) {
  const key = input.key;
  if (isPrimary) {
    return { type: input.type === 'video' ? 'video' : 'image', param: input.type === 'video' ? 'video_url' : 'image_url', label: input.label, required: !!input.required };
  }
  const isFrame = /^last_image(_url)?$/.test(key);
  return {
    type: input.type === 'video' ? 'video' : isFrame ? 'frame' : 'image',
    param: key,
    label: input.label,
    required: !!input.required,
  };
}

/** Phrases for one preset label, or the label itself. */
function presetPhrase(appId, label, data) {
  return data.presets?.[appId]?.[label] || label;
}

export function buildEditApp(app, data = prompts) {
  const s = app.studio;
  const model = app.endpoint.targetModel || app.endpoint.model;
  const outputKind = app.mediaType === 'video' ? 'video' : 'image';
  const route = V2V_MODELS.has(app.endpoint.model) ? 'v2v' : outputKind === 'video' ? 'i2v' : 'i2i';
  const [first, second] = s.mediaInputs;

  const controls = [];
  const presetValues = {};

  if (s.presets.length) {
    const labels = s.presets.map((p) => p.label);
    const hasSliders = s.sliders.length > 0;
    for (const p of s.presets) if (p.values) presetValues[p.label] = p.values;
    controls.push({
      type: 'preset',
      key: 'style_preset',
      label: hasSliders ? 'Preset' : 'Style',
      options: hasSliders ? ['Custom', ...labels] : labels,
      default: hasSliders ? 'Custom' : labels[0],
    });
  }

  for (const sl of s.sliders) {
    controls.push({
      type: 'range',
      key: `adj_${sl.key}`,
      label: sl.label,
      min: sl.min,
      max: sl.max,
      step: sl.step || 1,
      default: sl.default,
      unit: sl.unit || '',
      sliderKey: sl.key,
    });
  }

  for (const p of s.parameters) {
    if (!p.options?.length) continue;
    controls.push({
      type: 'select',
      key: p.key,
      label: p.label || p.key.replace(/_/g, ' '),
      options: p.options,
      default: p.default ?? p.options[0],
      optionLabel: SELECT_LABELS[p.key],
    });
  }

  return {
    id: `muapi-${app.id}`,
    slug: `app-${app.id}`,
    appId: app.id,
    isApp: true,
    name: app.name,
    description: app.description,
    howTo: app.description,
    category: app.studioTab,
    categoryKey: app.studioCategoryKey,
    thumbnail: app.thumbnail || null,
    model,
    route,
    outputKind,
    primary: mediaSource(first, true),
    secondary: second ? mediaSource(second, false) : null,
    controls,
    presetValues,
    hasPrompt: s.requiresPrompt !== false,
    promptBase: data.apps?.[app.id] || '{prompt}',
    presetPhrases: data.presets?.[app.id] || {},
    sliderPhrases: data.sliderPhrases || {},
    defaultCostUsd: s.defaultCostUsd,
    status: app.status,
    notes: app.notes || null,
  };
}

/**
 * The text sent to the model: the app's base prompt, with the chosen style, any moved
 * adjustments and the user's own words slotted into `{prompt}`.
 * @param {object} tool  an app from EDIT_APPS
 * @param {{style_preset?: string, adjustments?: Record<string, number>, extra?: string}} values
 */
export function buildAppPrompt(tool, { style_preset, adjustments = {}, extra = '' } = {}) {
  const parts = [];
  if (style_preset && style_preset !== 'Custom') parts.push(presetPhrase(tool.appId, style_preset, { presets: { [tool.appId]: tool.presetPhrases } }));
  for (const c of tool.controls.filter((x) => x.type === 'range')) {
    const v = adjustments[c.sliderKey];
    if (v === undefined || v === null || Number(v) === Number(c.default)) continue;
    const phrase = tool.sliderPhrases[c.sliderKey];
    if (phrase) parts.push(phrase.split('{value}').join(String(v)));
  }
  if (String(extra).trim()) parts.push(String(extra).trim());
  const core = parts.join(', ');
  let out = tool.promptBase.includes('{prompt}')
    ? tool.promptBase.replace(/\s*\{prompt\}/, core ? ` ${core}` : '')
    : [tool.promptBase, core].filter(Boolean).join(' ');
  out = out.replace(/\s+/g, ' ').trim();
  if (out && !/[.!?]$/.test(out)) out += '.';
  return out;
}

/** Split the values the Edit Studio reads from its controls into prompt inputs and request params. */
export function splitAppControlValues(values = {}) {
  const adjustments = {};
  const params = {};
  let style_preset;
  for (const [k, v] of Object.entries(values)) {
    if (k === 'style_preset') style_preset = v;
    else if (k.startsWith('adj_')) adjustments[k.slice(4)] = v;
    else params[k] = v;
  }
  return { style_preset, adjustments, params };
}

/** First missing input for an app, or null when it can run. */
export function validateAppInputs(tool, { primaryUrl, secondaryUrl } = {}) {
  const lower = (s) => (s ? s.charAt(0).toLowerCase() + s.slice(1) : s);
  if (!primaryUrl) return `Upload ${lower(tool.primary.label)} first.`;
  if (tool.secondary?.required && !secondaryUrl) return `Upload ${lower(tool.secondary.label)}.`;
  return null;
}

/** "$0.045", "$1.25", "$2.00": at least two decimals, up to three. */
export function formatAppCost(cost) {
  const n = Number(cost);
  if (!Number.isFinite(n)) return '';
  const three = String(Number(n.toFixed(3)));
  const decimals = (three.split('.')[1] || '').length;
  return `$${decimals >= 2 ? three : n.toFixed(2)}`;
}

export const EDIT_APPS = Object.freeze(
  appsMap.apps.filter((a) => !isAlreadyInThisRepo(a)).map((a) => buildEditApp(a)),
);

/** Apps left out because the same tool is already in this repo. */
export const SKIPPED_APPS = Object.freeze(
  appsMap.apps.filter(isAlreadyInThisRepo).map((a) => ({ id: a.id, name: a.name, existingIn: a.existingIn })),
);

export function getEditAppBySlug(slug) {
  return EDIT_APPS.find((a) => a.slug === slug) || null;
}

/** [{ key, label, apps }] in the same order as muapi's Studio tabs. */
export function getEditAppGroups() {
  return APP_CATEGORY_ORDER
    .map((key) => ({ key, apps: EDIT_APPS.filter((a) => a.categoryKey === key) }))
    .filter((g) => g.apps.length)
    .map((g) => ({ ...g, label: g.apps[0].category }));
}
